import{Z as a,e as t,f as r,a0 as n}from"./chunks/framework.DmpHOl9T.js";const f=JSON.parse('{"title":"Control Panel & Admin","description":"","frontmatter":{},"headers":[],"relativePath":"guides/control-panel-admin/index.md","filePath":"guides/control-panel-admin/index.md","lastUpdated":1782532814000}'),o={name:"guides/control-panel-admin/index.md"};function s(i,e,l,d,m,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="control-panel-admin" tabindex="-1">Control Panel &amp; Admin <a class="header-anchor" href="#control-panel-admin" aria-label="Permalink to &quot;Control Panel &amp; Admin&quot;">​</a></h1><p>Form groups, defaults, stencils, translations, and multi-site workflows.</p><h2 id="form-groups-and-defaults-at-scale" tabindex="-1"><a href="/guides/control-panel-admin/form-groups-and-defaults-at-scale">Form Groups and Defaults at Scale</a> <a class="header-anchor" href="#form-groups-and-defaults-at-scale" aria-label="Permalink to &quot;[Form Groups and Defaults at Scale](/guides/control-panel-admin/form-groups-and-defaults-at-scale)&quot;">​</a></h2><p>When a project grows past a handful of forms, the control panel gets noisy and new forms drift from your standards. Form groups organise the forms index, enforce policies, and layer group-level defaults on top of global Formie settings — without changing how forms render on the front end.</p><h2 id="import-and-export-between-environments" tabindex="-1"><a href="/guides/control-panel-admin/import-and-export-between-environments">Import and Export Between Environments</a> <a class="header-anchor" href="#import-and-export-between-environments" aria-label="Permalink to &quot;[Import and Export Between Environments](/guides/control-panel-admin/import-and-export-between-environments)&quot;">​</a></h2><p>Form import and export moves <strong>form definitions</strong> between environments — not submission data. Use it when staging a new form for production, cloning a client&#39;s enquiry form to another project, or backing up structure before a major edit.</p><h2 id="stencils-for-repeatable-form-types" tabindex="-1"><a href="/guides/control-panel-admin/stencils-for-repeatable-form-types">Stencils for Repeatable Form Types</a> <a class="header-anchor" href="#stencils-for-repeatable-form-types" aria-label="Permalink to &quot;[Stencils for Repeatable Form Types](/guides/control-panel-admin/stencils-for-repeatable-form-types)&quot;">​</a></h2><p>Stencils are reusable starter forms — layout, notifications, integrations, and settings included. They help teams spin up consistent enquiry, application, or survey forms without rebuilding the same field tree every time. This walkthrough builds a stencil, wires synced fields, and deploys it across environments.</p><h2 id="translating-forms-across-craft-sites" tabindex="-1"><a href="/guides/control-panel-admin/translating-forms-across-craft-sites">Translating Forms Across Craft Sites</a> <a class="header-anchor" href="#translating-forms-across-craft-sites" aria-label="Permalink to &quot;[Translating Forms Across Craft Sites](/guides/control-panel-admin/translating-forms-across-craft-sites)&quot;">​</a></h2><p>Multi-site Craft projects usually need the same form structure everywhere with different wording per site — not a completely different form per language. Formie stores one canonical layout and sparse per-site overrides for translatable text. This walkthrough takes a contact form from English source copy to French overrides without duplicating forms or fighting translation files.</p>',10)])])}const u=a(o,[["render",s]]);export{f as __pageData,u as default};
